add_action( 'woocommerce_after_checkout_form', 'perfectpixel_hide_shipping_on_pickup' );

function perfectpixel_hide_shipping_on_pickup() {
	?>
	<script>
	jQuery( function ( $ ) {
		var toggle = function () {
			var method = $( 'input.shipping_method:checked, input.shipping_method[type="hidden"]' ).first().val() || '';
			var pickup = method.indexOf( 'local_pickup' ) === 0 || method.indexOf( 'pickup_location' ) === 0;
			var $shipping = $( '.woocommerce-shipping-fields' );
			if ( pickup ) {
				$( '#ship-to-different-address-checkbox' ).prop( 'checked', false ).trigger( 'change' );
				$shipping.hide();
			} else {
				$shipping.show();
			}
		};
		$( document.body ).on( 'updated_checkout', toggle );
		$( 'form.checkout' ).on( 'change', 'input.shipping_method', toggle );
		toggle();
	} );
	</script>
	<?php
}
